#include "../firmware/include/controller.h"
#include <cassert>
#include <iostream>
int main(){ControlState s;ControlInput i;i.help=true;i.manual=true;i.sensorFault=true;s=step(s,i);assert(s.help&&s.duty==70&&!s.fanFault);i.help=false;i.now=3100;s=step(s,i);assert(s.help&&s.fanFault);i.ack=true;i.rpm=3000;s=step(s,i);assert(!s.help&&!s.fanFault);i.manual=false;i.automatic=true;s=step(s,i);assert(s.duty==0);i.sensorFault=false;s=step(s,i);assert(s.duty==50);s.started=0xfffffff0;s.duty=70;i.manual=true;i.now=4000;i.rpm=0;assert(step(s,i).fanFault);assert(!autoRequest(false,31.9f)&&autoRequest(false,32.0f));assert(autoRequest(true,31.2f)&&!autoRequest(true,30.9f));assert(!autoRequest(true,NAN));assert(autoRequest(true,38.9f)&&!autoRequest(true,39.0f)&&!autoRequest(false,38.7f)&&autoRequest(false,38.4f));assert(fanAdvice(36.9f)==FAN_OK&&fanAdvice(37.0f)==FAN_CAUTION&&fanAdvice(39.0f)==FAN_AVOID&&fanAdvice(NAN)==FAN_UNKNOWN);ControlState m;ControlInput hot;hot.manual=true;assert(step(m,hot).duty==70);std::cout<<"Controller tests passed: latch, manual, fault, startup, rollover, hysteresis, fan-benefit screen, manual never blocked\n";}
